INSERT INTO zootecnico.acerto_lote_resultado_geral (chave_lote, hash_linha, periodo_inicio, periodo_fim, unidade_extracao, origem_arquivo, codigo, integrado, local, tecnico, assist, planta_alimento, acerto_manual, gal, lote, dt_aloj, mao_de_obra, vazio_sanitario, aloj, mort, mort_2, ida, data_abate, qt_aves, ps_med, pes_total, pes_liq, consumo_racao, gpd, conv, cac, iep, kg_m2, calo, sx, linh, forneced, vl_medic, vlmedic_kgfg, vl_insumo, vlins_kgfg, custo_r, custo_kg, custo_cab, remun_prod_cab, remun_prod_kg, bonif_estrutura, bonif_condenacao, vl_liquido, vl_liquido_s_taxas, custo_pinto, custo_racao, custo_racao_total, frete, ps_med_pinto, composicao_lote_qtde_idd, densidade, frete_kg) SELECT s.chave_lote, s.hash_linha, s.periodo_inicio, s.periodo_fim, s.unidade_extracao, s.origem_arquivo, s.codigo, s.integrado, s.local, s.tecnico, s.assist, s.planta_alimento, s.acerto_manual, s.gal, s.lote, s.dt_aloj, s.mao_de_obra, s.vazio_sanitario, s.aloj, s.mort, s.mort_2, s.ida, s.data_abate, s.qt_aves, s.ps_med, s.pes_total, s.pes_liq, s.consumo_racao, s.gpd, s.conv, s.cac, s.iep, s.kg_m2, s.calo, s.sx, s.linh, s.forneced, s.vl_medic, s.vlmedic_kgfg, s.vl_insumo, s.vlins_kgfg, s.custo_r, s.custo_kg, s.custo_cab, s.remun_prod_cab, s.remun_prod_kg, s.bonif_estrutura, s.bonif_condenacao, s.vl_liquido, s.vl_liquido_s_taxas, s.custo_pinto, s.custo_racao, s.custo_racao_total, s.frete, s.ps_med_pinto, s.composicao_lote_qtde_idd, s.densidade, s.frete_kg FROM carga_acerto s WHERE NOT EXISTS (SELECT 1 FROM zootecnico.acerto_lote_resultado_geral t WHERE t.unidade_extracao=s.unidade_extracao AND BTRIM(t.codigo)=s.codigo AND BTRIM(t.gal)=s.gal AND BTRIM(t.lote)=s.lote AND t.dt_aloj::date=s.dt_aloj::date AND t.data_abate::date=s.data_abate::date);
