-- Dados brutos. Não altera views, funções, fórmulas ou schema.
BEGIN;
SET LOCAL standard_conforming_strings=on;
LOCK TABLE zootecnico.acerto_lote_resultado_geral IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE carga_acerto (LIKE zootecnico.acerto_lote_resultado_geral INCLUDING DEFAULTS) ON COMMIT DROP;


































DO $$ BEGIN IF EXISTS (SELECT s.chave_lote FROM carga_acerto s JOIN zootecnico.acerto_lote_resultado_geral t ON t.unidade_extracao=s.unidade_extracao AND BTRIM(t.codigo)=s.codigo AND BTRIM(t.gal)=s.gal AND BTRIM(t.lote)=s.lote AND t.dt_aloj::date=s.dt_aloj::date AND t.data_abate::date=s.data_abate::date GROUP BY s.chave_lote HAVING COUNT(*)>1) THEN RAISE EXCEPTION 'Mais de um registro existente para o mesmo lote. Carga revertida.'; END IF; END $$;

UPDATE zootecnico.acerto_lote_resultado_geral t SET hash_linha=s.hash_linha, periodo_inicio=s.periodo_inicio, periodo_fim=s.periodo_fim, unidade_extracao=s.unidade_extracao, origem_arquivo=s.origem_arquivo, codigo=s.codigo, integrado=s.integrado, local=s.local, tecnico=s.tecnico, assist=s.assist, planta_alimento=s.planta_alimento, acerto_manual=s.acerto_manual, gal=s.gal, lote=s.lote, dt_aloj=s.dt_aloj, mao_de_obra=s.mao_de_obra, vazio_sanitario=s.vazio_sanitario, aloj=s.aloj, mort=s.mort, mort_2=s.mort_2, ida=s.ida, data_abate=s.data_abate, qt_aves=s.qt_aves, ps_med=s.ps_med, pes_total=s.pes_total, pes_liq=s.pes_liq, consumo_racao=s.consumo_racao, gpd=s.gpd, conv=s.conv, cac=s.cac, iep=s.iep, kg_m2=s.kg_m2, calo=s.calo, sx=s.sx, linh=s.linh, forneced=s.forneced, vl_medic=s.vl_medic, vlmedic_kgfg=s.vlmedic_kgfg, vl_insumo=s.vl_insumo, vlins_kgfg=s.vlins_kgfg, custo_r=s.custo_r, custo_kg=s.custo_kg, custo_cab=s.custo_cab, remun_prod_cab=s.remun_prod_cab, remun_prod_kg=s.remun_prod_kg, bonif_estrutura=s.bonif_estrutura, bonif_condenacao=s.bonif_condenacao, vl_liquido=s.vl_liquido, vl_liquido_s_taxas=s.vl_liquido_s_taxas, custo_pinto=s.custo_pinto, custo_racao=s.custo_racao, custo_racao_total=s.custo_racao_total, frete=s.frete, ps_med_pinto=s.ps_med_pinto, composicao_lote_qtde_idd=s.composicao_lote_qtde_idd, densidade=s.densidade, frete_kg=s.frete_kg, carregado_em=CURRENT_TIMESTAMP FROM carga_acerto s WHERE t.unidade_extracao=s.unidade_extracao AND BTRIM(t.codigo)=s.codigo AND BTRIM(t.gal)=s.gal AND BTRIM(t.lote)=s.lote AND t.dt_aloj::date=s.dt_aloj::date AND t.data_abate::date=s.data_abate::date;


DO $$ BEGIN IF EXISTS (SELECT 1 FROM carga_acerto s WHERE NOT EXISTS (SELECT 1 FROM zootecnico.acerto_lote_resultado_geral t WHERE t.unidade_extracao=s.unidade_extracao AND BTRIM(t.codigo)=s.codigo AND BTRIM(t.gal)=s.gal AND BTRIM(t.lote)=s.lote AND t.dt_aloj::date=s.dt_aloj::date AND t.data_abate::date=s.data_abate::date AND t.hash_linha=s.hash_linha)) THEN RAISE EXCEPTION 'Conferência da carga falhou. Carga revertida.'; END IF; END $$;

SELECT COUNT(*) AS registros_conferidos FROM carga_acerto;
COMMIT;
